+  border-top: 1px solid rgba(29, 29, 31, 0.12);
+  padding: 40px 0 26px;
+}
+
+.footer-grid {
+  display: grid;
+  grid-template-columns: repeat(12, 1fr);
+  gap: 18px;
+}
+
+.footer-col {
+  grid-column: span 3;
+}
+
