+  font-size: 12px;
+  letter-spacing: 0.08em;
+  text-transform: uppercase;
+  color: rgba(29, 29, 31, 0.66);
+  margin: 0 0 10px;
+}
+
+.footer-links {
+  display: grid;
+  gap: 8px;
+}
+
+.footer-links a {
+  color: rgba(29, 29, 31, 0.78);
+  font-size: 13px;
+  text-decoration: none;
+}
+
+.footer-links a:hover {
+  text-decoration: underline;
+}
+
+.footer-legal {
+  margin-top: 26px;
+  font-size: 12px;
+  color: rgba(29, 29, 31, 0.62);
+  display: grid;
+  gap: 10px;
+}
+
+.footer-legal p {
+  margin: 0;
+}
+
+.footer-accordion {
+  display: none;
+}
+
+.footer-section {
+  border-top: 1px solid rgba(29, 29, 31, 0.12);
+}
+
+.footer-toggle {
+  width: 100%;
+  display: flex;
+  align-items: center;
+  justify-content: space-between;
+  padding: 14px 0;
+  background: transparent;
+  border: 0;
+  cursor: pointer;
+  font-size: 13px;
+  letter-spacing: 0.02em;
+  color: rgba(29, 29, 31, 0.86);
+}
+
+.footer-panel {
+  padding-bottom: 14px;
+  display: none;
+}
+
+.footer-panel a {
+  display: block;
+  padding: 7px 0;
+  color: rgba(29, 29, 31, 0.74);
+  font-size: 13px;
+  text-decoration: none;
+}
+
+.footer-panel a:hover {
+  text-decoration: underline;
+}
+
+.chev {
+  width: 16px;
+  height: 16px;
+  opacity: 0.75;
+  transition: transform 160ms ease;
+}
+
+.footer-section[aria-expanded="true"] .chev {
+  transform: rotate(180deg);
+}
+
+.footer-section[aria-expanded="true"] .footer-panel {
+  display: block;
+}
+
+/* Responsive */
+
+@media (max-width: 980px) {
+  .hero-grid {
+    grid-template-columns: 1fr;
+  }
+
+  .tile.span-6 {
+    grid-column: span 12;
+  }
+
+  .info {
+    grid-column: span 6;
+  }
+
+  .footer-col {
+    grid-column: span 6;
+  }
+}
+
+@media (max-width: 720px) {
+  .container {
+    width: min(var(--container), calc(100% - 32px));
+  }
+
+  .nav {
+    display: none;
+  }
+
+  .hero {
+    padding: 52px 0 32px;
+  }
+
+  .tile {
+    min-height: 320px;
+  }
+
+  .info {
+    grid-column: span 12;
+  }
+
+  .footer-grid {
+    display: none;
+  }
+
+  .footer-accordion {
+    display: block;
+  }
+}
+
